// The Receiver's icon, imported as a file: the import is the file's path,
// inside the executable when the Radio is compiled.
declare module '*.ico' {
  const path: string
  export default path
}
declare module '*.svg' {
  const path: string
  export default path
}
declare module '*.png' {
  const path: string
  export default path
}
declare module '*.wasm' {
  const path: string
  export default path
}
declare module '*.gz' {
  const path: string
  export default path
}
declare module '*.txt' {
  const path: string
  export default path
}
declare module '*.webmanifest' {
  const path: string
  export default path
}
declare module '*.woff2' {
  const path: string
  export default path
}
